587	\label{sec:types}
588	
589	The question distribution of the Pauli basis test is \emph{typed}: each question is a pair consisting of a type, drawn together with the other player's type from the edges of a fixed \emph{type graph}, and a question content, drawn from a CL distribution determined by the pair of types.
590	
591	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
592		\lean{MIPStarRE.QPBT.IsTypedCondLinearFamily}
593		\leanok
594		\uses{def:cl-func}
595		Let $\mathcal T$ be a finite set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$.
596	\end{definition}
597	
598	% Nonemptiness of the edge set is stated explicitly here: with E empty, m = k = 0 and the
599	% normalization 1/(2m-k) below is undefined. The source
600	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
601	\begin{definition}[Graph distribution]\label{def:graph-distribution}
602		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
603		\[
604			\mu_G(u, v) =
605			\begin{cases}
606				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
607				0 & \text{otherwise}\,.
608			\end{cases}
609		\]
610		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
611	\end{definition}
612	
613	% The nonempty-edge hypothesis on G is inherited from def:graph-distribution, where it is
614	% needed for the graph distribution mu_G to be defined; the source
615	% (references/qpbt-paper/07_types.tex:84-93) leaves it implicit here as well.
616	\begin{definition}[Typed conditionally linear distributions]\label{def:typed-cl-distributions}
617		\lean{MIPStarRE.QPBT.typedCLDistribution, MIPStarRE.QPBT.ldQuestionDistribution_eq_typedCL, MIPStarRE.QPBT.pauliQuestionDistribution_eq_typedCL}
618		\leanok
