447			where $\kappa(u_i) = (u_{ij})_{1 \le j \le \log q}$ under the bijection $\kappa\colon \F_q \to \F_2^{\log q}$ of Chapter~\ref{chap:qpbt-algebra}.
448		\end{enumerate}
449	\end{corollary}
450	\begin{proof}
451		\uses{thm:pauli, lem:pauli-binary}
452		By Lemma~\ref{lem:pauli-binary}, since $q$ is a power of $2$ there are local isometries that map $\ket{\mathrm{EPR}_q}^{\ot M}$ to $\ket{\mathrm{EPR}_2}^{\ot M \log q}$ and map the generalized Pauli measurements $\tau^W_u$ to the qubit tensor products $\bigotimes_{i=1}^M \bigotimes_{j=1}^{\log q} \sigma^W_{u_{ij}}$, where $\kappa(u_i) = (u_{i1},\ldots,u_{i \log q})$. Composing these isometries with those produced by Theorem~\ref{thm:pauli} gives the statement.
453	\end{proof}
