192	\section{The Magic Square game}
193	% Paper label sec:ms kept for cross-reference fidelity.
194	\label{sec:ms}
195	
196	We recall the Magic Square game of Mermin and Peres. It is a simple self-test for two EPR pairs, and it allows one to test that a pair of binary observables \emph{anticommutes}; both properties are used in the Pauli basis test. Here it is presented as a binary constraint satisfaction game. Throughout this section and the next, $\sigma^X$ and $\sigma^Z$ denote the single-qubit Pauli observables, with associated two-outcome projective measurements $\{\sigma^W_b\}_{b \in \F_2}$ for $W \in \{X,Z\}$.
197	
198	\begin{definition}[The Magic Square game]\label{def:ms-game}
199		\uses{def:game, def:graph-distribution}
200		The Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ is the following two-player game. There are $9$ variables $x_1,\ldots,x_9$ taking values in $\F_2$, arranged in a $3 \times 3$ grid: the cell in row $r$ and column $c$ contains the variable $x_{3(r-1)+c}$. There are $6$ linear equations over these variables: for each of the three rows and each of the first two columns, the sum of the three variables in it equals $0$; for the third column, the sum of the three variables in it equals $1$.
201	
202		The question types are
203		\begin{align*}
204			\mathcal T^{\mathrm{mc}} &= \{\mathsf{Constraint}_i : i = 1,2,\ldots,6\}\;,\\
205			\mathcal T^{\mathrm{mv}} &= \{\mathsf{Variable}_j : j = 1,2,\ldots,9\}\;,\\
206			\mathcal T^{\mathrm{ms}} &= \mathcal T^{\mathrm{mc}} \cup \mathcal T^{\mathrm{mv}}\;,
207		\end{align*}
208		where $\mathsf{Constraint}_i$ for $i \in \{1,2,3\}$ denotes the constraint of row $i$ (with variables $x_{3(i-1)+1}, x_{3(i-1)+2}, x_{3(i-1)+3}$), $\mathsf{Constraint}_4$ and $\mathsf{Constraint}_5$ denote the constraints of the first two columns, and $\mathsf{Constraint}_6$ denotes the constraint of the third column (with variables $x_{i-3}, x_{i}, x_{i+3}$ for $\mathsf{Constraint}_i$, $i \in \{4,5,6\}$).
209	
210		The question distribution is as follows: the verifier samples $\mathsf{Constraint}_i$ uniformly from $\mathcal T^{\mathrm{mc}}$, then samples $\mathsf{Variable}_j$ uniformly among the three variables appearing in the row or column of $\mathsf{Constraint}_i$; one player, chosen uniformly at random, receives $\mathsf{Constraint}_i$ and the other receives $\mathsf{Variable}_j$. Equivalently, the verifier samples a uniformly random edge of the bipartite \emph{type graph} $G^{\mathrm{ms}}$ on vertex sets $\mathcal T^{\mathrm{mc}}$ and $\mathcal T^{\mathrm{mv}}$, whose edges are $\mathsf{Constraint}_i \,\text{---}\, \mathsf{Variable}_{3(i-1)+j}$ for $i,j \in \{1,2,3\}$ and $\mathsf{Constraint}_i \,\text{---}\, \mathsf{Variable}_{(i-3)+3(j-1)}$ for $i \in \{4,5,6\}$, $j \in \{1,2,3\}$ ($18$ edges in total, and no self-loops), and sends one endpoint to a uniformly random player and the other endpoint to the other player.
211	
212		The $\mathsf{Constraint}$ player answers with three bits $(\beta_{v_1}, \beta_{v_2}, \beta_{v_3}) \in \F_2^3$, where $(v_1,v_2,v_3)$ are the indices of the three variables of $\mathsf{Constraint}_i$; the $\mathsf{Variable}$ player answers with a single bit $\gamma \in \F_2$. The players win if and only if the $\mathsf{Constraint}$ player's answer satisfies the equation associated with $\mathsf{Constraint}_i$ and $\gamma = \beta_j$.
213	\end{definition}
214	
215	The following theorem records the self-testing (rigidity) properties of the Magic Square game. It is used in the soundness analysis of the Pauli basis test to enforce anticommutation relations between certain pairs of observables.
216	
217	\begin{theorem}[Rigidity of the Magic Square game]\label{thm:ms-rigidity}
218		\lean{MIPStarRE.QPBT.exists_ms_rigidity}
219		\leanok
220		\uses{def:ms-game, def:tensor-product-value, def:EPR, def:povm-distance}
221		Let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy that succeeds in the Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ with probability $1-\eps$, where $\ket{\psi} \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$. Then there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\hilb_{\mathrm A'}, \hilb_{\mathrm B'} \cong (\C^2)^{\ot 2}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''}$ are finite dimensional, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A''} \ot \hilb_{\mathrm B''}$, such that:
222		\begin{enumerate}
223			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket{\psi} - \ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}} \bigr\| \le O(\sqrt\eps)$;
224			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$,
225			\begin{align*}
226				\tilde A^{\mathsf{Variable}_1}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^X_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
227				\tilde A^{\mathsf{Variable}_5}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^Z_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
228				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^X_b)_{\mathrm B'}\;,\\
229				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^Z_b)_{\mathrm B'}\;,
230			\end{align*}
231			where each $\approx_{\sqrt\eps}$ holds with respect to the state $\ket{\mathrm{EPR}_2}^{\ot 2}_{\mathrm{A'B'}} \ot \ket{\mathrm{aux}}_{\mathrm{A''B''}}$ and the answer summation is over $b \in \{0,1\}$, and the approximation bounds carry implicit universal constants.
232		\end{enumerate}
233		As a consequence, letting $\tilde A^{\mathsf{Variable}_1} = \tilde A^{\mathsf{Variable}_1}_0 - \tilde A^{\mathsf{Variable}_1}_1$ and $\tilde A^{\mathsf{Variable}_5} = \tilde A^{\mathsf{Variable}_5}_0 - \tilde A^{\mathsf{Variable}_5}_1$ denote the associated observables, it holds that
234		\begin{align*}
235			\tilde A^{\mathsf{Variable}_1} \tilde A^{\mathsf{Variable}_5} \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} -\, \tilde A^{\mathsf{Variable}_5} \tilde A^{\mathsf{Variable}_1} \ot I_{\mathrm{B'B''}}\;,\\
236			I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1} \tilde B^{\mathsf{Variable}_5} &\approx_{\sqrt\eps} -\, I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5} \tilde B^{\mathsf{Variable}_1}\;,
237		\end{align*}
238		where, for operators $M$, $N$ that are not POVM elements, the notation $M \approx_\delta N$ means $\bra{\psi} (M-N)^\dagger (M-N) \ket{\psi} \le O(\delta)$ with respect to the same state.
239	\end{theorem}
240	\begin{proof}
241		This result is imported from Theorem~6.9 of~\cite{Coladangelo2017Robust}. There are two minor differences between their statement and the one given here. First, they state a robustness of $O(\eps)$, but measure the closeness of the actual and ideal states in trace norm; expressed as the Euclidean distance between $\phi_{\mathrm A} \ot \phi_{\mathrm B}\ket{\psi}$ and $\ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}}$, this becomes $O(\sqrt\eps)$. Second, their ideal observables for the $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ questions are $I \ot \sigma^Z$ and $\sigma^Z\sigma^X \ot \sigma^Z\sigma^X$; under a local change of basis these are equivalent to $\sigma^X \ot I$ and $\sigma^Z \ot I$, respectively.
242	\end{proof}
243	
